import json
import itertools

def solve():
    houses = [1, 2, 3]  # left (1) to right (3)

    # Categories and their values
    Names = ['Arnold', 'Peter', 'Eric']
    Animals = ['bird', 'horse', 'cat']
    Birthdays = ['jan', 'sept', 'april']
    Hobbies = ['photography', 'cooking', 'gardening']
    Drinks = ['milk', 'water', 'tea']
    HairColors = ['black', 'brown', 'blonde']

    def pos(seq, value):
        return seq.index(value)

    solution = None

    # Iterate through permutations for each category, applying constraints progressively
    for name_perm in itertools.permutations(Names):
        # Constraint 3: Eric is not in the first house.
        if name_perm[0] == 'Eric':
            continue

        # Precompute index of Arnold
        idx_arnold = pos(name_perm, 'Arnold')

        for animal_perm in itertools.permutations(Animals):
            # Constraint 4: The cat lover is in the second house.
            if animal_perm[1] != 'cat':
                continue

            # Constraint 8: Arnold is the bird keeper.
            if animal_perm[idx_arnold] != 'bird':
                continue

            for birthday_perm in itertools.permutations(Birthdays):
                # Constraint 2: April is in the third house.
                if birthday_perm[2] != 'april':
                    continue

                # Constraint 10: September is directly left of Arnold.
                # Arnold cannot be in the first house.
                if idx_arnold == 0:
                    continue
                if birthday_perm[idx_arnold - 1] != 'sept':
                    continue

                for hair_perm in itertools.permutations(HairColors):
                    # Constraint 7: The cat lover is the person who has brown hair.
                    # Cat lover is in house 2 -> hair in house 2 must be brown.
                    if hair_perm[1] != 'brown':
                        continue

                    for hobby_perm in itertools.permutations(Hobbies):
                        # Constraint 1: Brown hair <-> Cooking (same house).
                        if pos(hair_perm, 'brown') != pos(hobby_perm, 'cooking'):
                            continue

                        for drink_perm in itertools.permutations(Drinks):
                            # Constraint 6: Gardening = Milk (same house).
                            if pos(hobby_perm, 'gardening') != pos(drink_perm, 'milk'):
                                continue

                            # Constraint 9: Water = Photography (same house).
                            if pos(drink_perm, 'water') != pos(hobby_perm, 'photography'):
                                continue

                            # Constraint 5: Blonde is somewhere to the left of Milk.
                            if not (pos(hair_perm, 'blonde') < pos(drink_perm, 'milk')):
                                continue

                            # All constraints satisfied, build solution
                            rows = []
                            for i, house in enumerate(houses):
                                rows.append([
                                    str(house),
                                    name_perm[i],
                                    animal_perm[i],
                                    birthday_perm[i],
                                    hobby_perm[i],
                                    drink_perm[i],
                                    hair_perm[i]
                                ])
                            solution = {
                                "solution": {
                                    "header": ["House", "Name", "Animal", "Birthday", "Hobby", "Drink", "HairColor"],
                                    "rows": rows
                                }
                            }
                            return solution  # Unique solution expected; return immediately

    return None

if __name__ == "__main__":
    res = solve()
    if res is None:
        # Fallback to ensure valid JSON output even if no solution found
        print(json.dumps({"solution": {"header": ["House", "Name", "Animal", "Birthday", "Hobby", "Drink", "HairColor"], "rows": []}}))
    else:
        print(json.dumps(res))
